/* Lightweight local fallback for Chart usage in MVP templates. */
(function () {
  if (window.Chart) return;
  window.Chart = function (ctx, cfg) {
    try {
      if (!ctx || !ctx.getContext) return;
      var canvasCtx = ctx.getContext("2d");
      var data = (cfg && cfg.data && cfg.data.datasets && cfg.data.datasets[0] && cfg.data.datasets[0].data) || [];
      var labels = (cfg && cfg.data && cfg.data.labels) || [];
      var width = ctx.width || ctx.clientWidth || 600;
      var height = ctx.height || ctx.clientHeight || 220;
      ctx.width = width;
      ctx.height = height;
      canvasCtx.clearRect(0, 0, width, height);
      canvasCtx.fillStyle = "#7aa2ff";
      var maxVal = Math.max.apply(null, data.concat([1]));
      var barW = width / Math.max(1, data.length * 1.4);
      data.forEach(function (v, i) {
        var h = (v / maxVal) * (height - 30);
        var x = 12 + i * (barW * 1.4);
        var y = height - h - 20;
        canvasCtx.fillRect(x, y, barW, h);
        canvasCtx.fillStyle = "#99a9bf";
        canvasCtx.fillText(String(labels[i] || i + 1), x, height - 6);
        canvasCtx.fillStyle = "#7aa2ff";
      });
    } catch (_) {}
  };
})();
